/**
 * @file memcard.c
 * @brief Save-data SHA-1 and memory-card task unit (0x801CBBAC - 0x801D0AA0).
 *
 * Candidate reconstruction of the whole translation unit. Its sections are
 * .text 0x801CBBAC-0x801D0AA0, .rodata 0x802758E8-0x80279320 (banner, icon,
 * file-name strings), .data 0x8036DE70-0x8036E030 (the switch tables of
 * memcardTaskMain, fn_801CF9C8 and fn_801D0090), .bss 0x804670E8-0x80467378,
 * .sdata2 0x8047E160-0x8047E180 and .sbss 0x8047B3D0-0x8047B3D8.
 *
 * Unit flags: GC/2.5 -O4,p, -str reuse,readonly, -inline deferred.
 * Evidence for deferred inlining: with it MWCC emits the functions of a file
 * in reverse order and lays out .bss in reverse declaration order; this
 * source is written in reverse address order and gives the retail text
 * order and the retail .bss layout (SHA1Transform's workspace at +0x00, the
 * saved digest at +0x40, the block digest at +0x54, the key at +0x68). With
 * it savedataDecryptCheck reaches the digest buffers off the unit's .bss base while
 * fn_801CBE44 names them directly, as retail does, and fn_801D0748 inlines
 * fn_801D055C (defined after it in the file).
 *
 * The small per-state handlers of memcardTaskMain are static inline functions
 * returning the next state, like the five large ones that were not inlined
 * (memcardSaveSetup, fn_801CF568, fn_801CF7E4, fn_801CF9C8, fn_801CFD08). Their
 * returns give retail's shared "store next state" tails, and the handlers
 * whose early returns join (header read, write check, finish) cannot be
 * written as one flat case.
 *
 * task_kind and error_code are volatile: retail re-reads task_kind in nested
 * switches with no intervening store, and keeps the self-assignment
 * "error_code = error_code" in the end-access handler, which MWCC removes for
 * a non-volatile field.
 *
 * Status: all 23 functions are exact and the whole TU links (lane D9). The
 * last two:
 * - memcardTaskMain: the last-write check polls through memcardPollResultInto,
 *   which keeps the polled result in the caller's register (r30) for the
 *   store (RULE-EXCEPTION, listed in docs/RULE_EXCEPTIONS.md).
 * - fn_801CF9C8: the slot-header loop reads through a `task` copy of the
 *   state pointer and addresses each header as work_buffer + offset, without
 *   a header variable (retail colours the offset before the task pointer);
 *   the selected slot header is work_buffer + 0x1E000 + index * 0x200 and
 *   its save data header + 2 words, whose split constant gives retail's
 *   `addis; add r28,r0,r4; addi -0x1FF8`.
 * lbl_8047B3D0 and lbl_8047B3D4 are external: field_range_801CB180.c uses
 * them. sRandomArea is 8-byte aligned (retail 0x80467168).
 */
#include "dolphin/types.h"
#include "game/save/savedata_sha1.h"

typedef struct MemcardFileStatus {
    char file_name[0x20];
    u32 length;
    u32 time;
    u32 game_code;
    u16 company_code;
    u8 banner_format;
    u8 padding;
    u32 icon_address;
    u16 icon_format;
    u16 icon_speed;
    u32 comment_address;
    u32 banner_offset;
    u32 banner_tlut_offset;
    u32 icon_offsets[8];
    u32 icon_tlut_offset;
    u32 data_offset;
} MemcardFileStatus;

typedef struct SavedataBody {
    u8 data[0x1DFD0];
} SavedataBody;

/* Same size as SavedataBody; copied by value between the card image and the
 * live save data. */
typedef struct SavedataPayload {
    u8 bytes[0x1DFD0];
} SavedataPayload;

/* One 0x200-byte slot header after the save data (three of them). Word 1
 * holds the save count and word 3 makes the eight first words sum to zero. */
typedef struct MemcardSlotHeader {
    u32 words[0x80];
} MemcardSlotHeader;

typedef struct MemcardWorkBuffer {
    u8 header[8];
    SavedataBody savedata;
    u8 random[0x14];
    u8 hash[0x14];
    MemcardSlotHeader slot[3];
} MemcardWorkBuffer;

typedef struct MemcardDiskId {
    u32 game_code;
    u16 company_code;
    u8 disk_number;
    u8 game_version;
    u8 streaming;
    u8 streaming_buffer_size;
    u8 padding[0x16];
} MemcardDiskId;

typedef struct MemcardTaskState {
    volatile s32 task_kind;
    volatile s32 error_code;
    s32 task_result;
    s32 state;
    s32 resume_state;
    s32 card_channel;
    s32 mem_size;
    s32 sector_size;
    s32 field_20;
    s32 retry_count;
    s32 card_result;
    s32 field_2c;
    u32 serial_hi;
    s32 random_delay;
    u32 write_ticks;
    u8 callback_finished;
    u8 field_3d;
    u8 dialog_result;
    u8 initial_dialog_result;
    u8 format_requested;
    u8 serial_check_enabled;
    u64 card_serial;
    MemcardWorkBuffer* work_buffer;
    void* card_work_area;
    SavedataBody* savedata_status;
    s32 card_work_size;
    s32 next_state_after_delay;
    void* gapp;
    MemcardDiskId* disk_id;
    MemcardDiskId mounted_disk_id;
    struct {
        s32 chan;
        s32 file_no;
        u32 offset;
        u32 length;
        u16 start_block;
    } file_info;
    MemcardFileStatus stat;
} MemcardTaskState;


MemcardTaskState* lbl_8047B3D4;

typedef struct SavedataBlock {
    u8 field_0000[0xB328];
    u8 field_B328[0x16B4];
    u8 field_C9DC[0x1F8];
    u8 field_CBD4[0x58];
} SavedataBlock;

typedef union MemcardSaveHeader {
    struct {
        u8 valid;
        u8 initialized;
        u8 field_02;
        u8 field_03;
        s32 save_count;
        u8 savedata[0x18];
    } fields;
    u32 words[8];
} MemcardSaveHeader;

typedef struct MemcardSaveBuffer {
    MemcardSaveHeader header;
    u32 field_20;
    u8 field_24[0x1DFB4];
    u8 random[20];
    u8 hash[0x18];
} MemcardSaveBuffer;



#define CARD_RESULT_READY 0
#define CARD_RESULT_BUSY -1
#define CARD_RESULT_NOFILE -4
#define CARD_RESULT_BROKEN -6
#define CARD_RESULT_ENCODING -13

#define CARD_STAT_ICON_C8 1
#define CARD_STAT_ICON_MASK 3
#define CARD_STAT_BANNER_RGB5A3 2
#define CARD_STAT_BANNER_MASK 3
#define CARD_STAT_ANIM_LOOP 0x00
#define CARD_STAT_ANIM_MASK 0x04
#define CARD_STAT_SPEED_MIDDLE 2
#define CARD_STAT_SPEED_MASK 3

#define CARDSetIconAddress(stat, addr) ((stat)->icon_address = (u32)(addr))
#define CARDSetCommentAddress(stat, addr) ((stat)->comment_address = (u32)(addr))
#define CARDSetBannerFormat(stat, f) \
    ((stat)->banner_format = (u8)(((stat)->banner_format & ~CARD_STAT_BANNER_MASK) | (f)))
#define CARDSetIconAnim(stat, f) \
    ((stat)->banner_format = (u8)(((stat)->banner_format & ~CARD_STAT_ANIM_MASK) | (f)))
#define CARDSetIconFormat(stat, n, f) \
    ((stat)->icon_format = (u16)(((stat)->icon_format & ~(CARD_STAT_ICON_MASK << (2 * (n)))) | \
                                 ((f) << (2 * (n)))))
#define CARDSetIconSpeed(stat, n, f) \
    ((stat)->icon_speed = (u16)(((stat)->icon_speed & ~(CARD_STAT_SPEED_MASK << (2 * (n)))) | \
                                ((f) << (2 * (n)))))

typedef struct MemcardIconFile {
    char title[0x20];
    char comment[0x20];
    u8 banner[0x1800];
    u8 icon[0x2200];
    u32 checksum;
} MemcardIconFile;

